/** SymPy's doctests and unit tests of this module with SymPy's printed results. Generated by compat/totests from the SymPy corpora; do not edit. */

import { describe, expect, it } from 'vitest';
import { Add, Mul, Pow, Sym, add, exp, fn, gosperNormal, gosperSum, gosperTerm, log, mul, pow, rational, rewrite, simplify, symbols } from '../../src';
import { at, sympyMatches, sympyStr } from '../sympy-str';

describe("doctests of sympy.concrete.gosper", () => {
  it("gosper_normal(4*n+5, 2*(4*n+1)*(2*n+3), n, polys=False)", () => {
    const n = new Sym('n');
    const v1 = gosperNormal(add(5, mul(4, n)), mul(add(2, mul(8, n)), add(3, mul(2, n))), n, { polys: false });
    expect(sympyMatches([at(v1, 0), at(v1, 1), at(v1, 2)], '(1/4, n + 3/2, n + 1/4)')).toBe(true);
  });
  it("gosper_sum(f, (k, 0, n))", () => {
    const [k, n] = symbols('k n');
    expect(sympyStr(gosperSum(mul(pow(fn('factorial', [add(1, mul(2, k))]), -1), add(1, mul(4, k)), fn('factorial', [k])), [k, 0, n]))).toBe('(-factorial(n) + 2*factorial(2*n + 1))/factorial(2*n + 1)');
  });
  it("gosper_sum(f, (k, 3, n))", () => {
    const [k, n] = symbols('k n');
    expect(sympyStr(gosperSum(mul(pow(fn('factorial', [add(1, mul(2, k))]), -1), add(1, mul(4, k)), fn('factorial', [k])), [k, 3, n]))).toBe('(-60*factorial(n) + factorial(2*n + 1))/(60*factorial(2*n + 1))');
  });
  it("gosper_term((4*n + 1)*factorial(n)/factorial(2*n + 1), n)", () => {
    const n = new Sym('n');
    expect(sympyStr(gosperTerm(mul(pow(fn('factorial', [add(1, mul(2, n))]), -1), add(1, mul(4, n)), fn('factorial', [n])), n))).toBe('(-n - 1/2)/(n + 1/4)');
  });
});

